    f['deg2']=sum(1 for v in deg.values() if v==2); f['deg3']=sum(1 for v in deg.values() if v==3)
    rowcounts=[sum((r,c) in p for c in range(3)) for r in range(3)]
    colcounts=[sum((r,c) in p for r in range(3)) for c in range(3)]
    f['maxrow']=max(rowcounts); f['maxcol']=max(colcounts); f['minrow']=min(rowcounts); f['mincol']=min(colcounts)
    f['singlerows']=sum(1 for x in rowcounts if x==1); f['singlecols']=sum(1 for x in colcounts if x==1)
    f['fullrows']=sum(1 for x in rowcounts if x==3); f['fullcols']=sum(1 for x in colcounts if x==3)
