    f['hruns2']=sum(1 for r in hrs for x in r if x>=2); f['vruns2']=sum(1 for r in vrs for x in r if x>=2)
    f['hruns3']=sum(1 for r in hrs for x in r if x>=3); f['vruns3']=sum(1 for r in vrs for x in r if x>=3)
    f['allruns']=f['hruns']+f['vruns']
    f['maxh']=max([max(r,default=0) for r in hrs]); f['maxv']=max([max(r,default=0) for r in vrs])
    f['diag1']=len({r+c for r,c in p}); f['diag2']=len({r-c for r,c in p})
