    seen=set(); comp=0
    for cell in sorted(p):
        if cell in seen: continue
        comp+=1; st=[cell]
        while st:
            x=st.pop()
            if x in seen: continue
            seen.add(x)
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                if (x[0]+dr,x[1]+dc) in p: st.append((x[0]+dr,x[1]+dc))
    f['comp']=comp
    for nm,fn in [('rot180',lambda r,c:(2-r,2-c)),('fliph',lambda r,c:(r,2-c)),('flipv',lambda r,c:(2-r,c)),('rot90',lambda r,c:(c,2-r))]:
        q={fn(r,c) for r,c in p}
